+gint32
+dlt_ecu_id_to_gint32(const gchar *ecu_id) {
+    if (ecu_id == NULL) {
+        return 0;
+    }
+
+    gint32 ret = 0;
+    gint i;
+    guint shift = 32;
+
+    /* DLT allows only up to 4 ASCII chars! Unused is 0x00 */
+    for (i = 0; i < (gint)strlen(ecu_id) && i < 4; i++) {
+        shift -= 8;
+        ret |= (gint32)ecu_id[i] << shift;
+    }
+
+    return ret;
+}
