+
+static gboolean
+update_spdu_dlt_mapping(void *r, char **err) {
+    spdu_dlt_mapping_uat_t *rec = (spdu_dlt_mapping_uat_t *)r;
+
+    if (rec->ecu_id != NULL && strlen(rec->ecu_id) > 4) {
+            *err = ws_strdup_printf("ECU ID can only be up to 4 characters long!");
+        return FALSE;
+    }
+
